from pathlib import Path
import hashlib, json, re

home=Path.home()
bridge=home/'.local/share/prediction-chat-bridge'
bus_state=home/'.local/state/prediction-command-bus/tasks'
ids=[
 'TM-PING-1790690332005',
 'BRIDGE-COMMAND-BUS-CURRENT-ROUTE-E008',
 'BRIDGE-COMMAND-BUS-TEST-1790691850',
 'TM-PING-20260929-1630-E001',
 'TM-PING-20260929-RETRY-E002',
]

def digest(value):
    return hashlib.sha256(str(value or '').encode()).hexdigest()[:12] if value else '-'

def jload(path):
    try: return json.loads(path.read_text(encoding='utf-8'))
    except Exception: return None

print('ROUTE_BOOTSTRAP_DIAG_E009=START')
for task in ids:
    route=jload(bridge/'routes'/f'{task}.json')
    state=jload(bus_state/f'{task}.json')
    queues=[]
    for q in ('outbox','inflight','sent','quarantine'):
        d=bridge/q
        if d.exists():
            for p in d.glob('*.json'):
                obj=jload(p)
                if isinstance(obj,dict) and str(obj.get('task_id') or '')==task:
                    queues.append(q)
                    break
    print('TASK',task,'route',bool(route),'chat',digest(route.get('chat_id') if route else ''),'consumer',digest(route.get('consumer_id') if route else ''),'bus',state.get('status') if state else '-','queues',','.join(queues) or '-')

route_dir=bridge/'routes'
recent=[]
if route_dir.exists():
    for p in route_dir.glob('*.json'):
        try: recent.append((p.stat().st_mtime,p))
        except OSError: pass
recent.sort(reverse=True)
print('RECENT_ROUTES',len(recent))
for _,p in recent[:12]:
    obj=jload(p) or {}
    print('ROUTE',p.stem,'chat',digest(obj.get('chat_id')),'consumer',digest(obj.get('consumer_id')),'source',str(obj.get('source') or '-'))

for name in ('prediction-chat-wake.user.js','bridge_server.py','bridge_server_v2.py','command_router.py'):
    p=bridge/name
    if not p.exists():
        print('RUNTIME_FILE',name,'MISSING'); continue
    text=p.read_text(encoding='utf-8',errors='replace')
    version='-'
    m=re.search(r'@version\s+([^\s]+)',text) or re.search(r'server_version\s*=\s*[\"\']([^\"\']+)',text)
    if m: version=m.group(1)
    print('RUNTIME_FILE',name,'sha',hashlib.sha256(text.encode()).hexdigest()[:16],'version',version,'bytes',len(text.encode()))

print('ROUTE_BOOTSTRAP_DIAG_E009=PASS')
